mapper.select:
select u.id as userId, u.username as username, u.email as email, u.avatar as avatar, latest.member_type as memberType, case latest.member_type when 'vip' then 'VIP Member' when 'small_class' then 'Small Class Member' else latest.member_type end as memberTypeName, case latest.member_type when 'vip' then 'VIP用户' when 'small_class' then '小班用户' else latest.role_name end as planName, 1 as memberActive, date_format(latest.expire_time, '%Y-%m-%d %H:%i:%s') as memberExpireTime, coalesce(course_total.total_course_count, 0) as totalCourseCount, coalesce(progress_summary.started_course_count, 0) as startedCourseCount, coalesce(progress_summary.completed_course_count, 0) as completedCourseCount, case when coalesce(course_total.total_course_count, 0) > 0 then round(coalesce(progress_summary.total_progress_percent, 0) / course_total.total_course_count, 2) else 0.00 end as overallProgress, case when coalesce(course_total.total_course_count, 0) > 0 then round(coalesce(progress_summary.started_course_count, 0) * 100.00 / course_total.total_course_count, 2) else 0.00 end as startRate, case when coalesce(course_total.total_course_count, 0) > 0 then round(coalesce(progress_summary.completed_course_count, 0) * 100.00 / course_total.total_course_count, 2) else 0.00 end as completionRate, date_format(progress_summary.last_learn_time, '%Y-%m-%d %H:%i:%s') as lastLearnTime from osh_user u inner join (
) latest on latest.user_id = u.id left join ( select t.user_id, count(distinct t.course_id) as total_course_count from ( select ocb.user_id, ocb.course_id from osh_course_buy ocb where ocb.pay_status = 'paid' and ocb.delete_flag = 0 union all select oucp.user_id, oucp.course_id from osh_user_course_progress oucp where oucp.delete_flag = 0 ) t group by t.user_id ) course_total on course_total.user_id = u.id left join ( select user_id, count(distinct course_id) as started_course_count, sum(coalesce(progress_percent, 0)) as total_progress_percent, sum(case when coalesce(is_completed, 0) = 1 then 1 else 0 end) as completed_course_count, max(last_learn_time) as last_learn_time from osh_user_course_progress where delete_flag = 0 group by user_id ) progress_summary on progress_summary.user_id = u.id where u.delete_flag = 0
and (u.username like concat('%', #{query.keyword}, '%') or u.email like concat('%', #{query.keyword}, '%'))
and latest.member_type = #{query.memberType}
and latest.expire_time is not null and latest.expire_time > now()
order by progress_summary.last_learn_time desc, latest.expire_time desc, u.id desc

mapper.insert:
insert ignore into osh_internal_member_employment_profile (
    user_id, create_by, create_time, update_by, update_time, delete_flag
) values (
    #{userId}, #{operatorId}, now(), #{operatorId}, now(), 0
)

mapper.select:
select u.id as userId, u.username as username, u.email as email, u.avatar as avatar, latest.member_type as memberType, case latest.member_type when 'vip' then 'VIP Member' when 'small_class' then 'Small Class Member' else latest.member_type end as memberTypeName, p.job_status as jobStatus, p.job_status_name as jobStatusName, p.company_name as companyName, p.position_name as positionName, p.city as city, p.salary_before as salaryBefore, p.salary_after as salaryAfter, p.target_salary as targetSalary, case when p.salary_before is not null and p.salary_after is not null then round(p.salary_after - p.salary_before, 2) else null end as salaryIncrease, date_format(p.entry_time, '%Y-%m-%d %H:%i:%s') as entryTime, p.case_eligible as caseEligible, p.resume_delivery_count as resumeDeliveryCount, p.interview_company_count as interviewCompanyCount, p.pending_interview_count as pendingInterviewCount, p.completed_interview_count as completedInterviewCount, p.interview_round_count as interviewRoundCount, p.interview_status as interviewStatus, p.interview_result as interviewResult, date_format(follow_summary.last_follow_time, '%Y-%m-%d %H:%i:%s') as lastFollowTime, date_format(follow_summary.next_follow_time, '%Y-%m-%d %H:%i:%s') as nextFollowTime from osh_user u inner join (
) latest on latest.user_id = u.id left join osh_internal_member_employment_profile p on p.user_id = u.id and p.delete_flag = 0 left join ( select user_id, max(create_time) as last_follow_time, max(next_follow_time) as next_follow_time from osh_internal_member_follow_record where delete_flag = 0 group by user_id ) follow_summary on follow_summary.user_id = u.id where u.delete_flag = 0
and (u.username like concat('%', #{query.keyword}, '%') or u.email like concat('%', #{query.keyword}, '%') or p.company_name like concat('%', #{query.keyword}, '%') or p.position_name like concat('%', #{query.keyword}, '%'))
and p.job_status = #{query.jobStatus}
and p.salary_before is not null and p.salary_after is not null and (p.salary_after - p.salary_before) >= #{query.minSalaryIncrease}
and p.case_eligible = #{query.caseEligible}
order by case when p.case_eligible = 1 then 1 else 0 end desc, p.update_time desc, u.id desc
